        x_sign: -1;
    ];
    if[(leading_coefficient < 0);
        x_sign: 1;
    ];

    x_start: x_sign * (abs(leading_coefficient) + 1);

    f:{[coeffs;degree;xval]
        i: degree;
        total: 0;
        while[i >= 0;
            total: total + (xval * xval * coeffs[i]) + (xval * coeffs[i - 1]);
            i: i - 2;
        ];
        :total;
    };

    df:{[coeffs;degree;xval]
        i: degree;
        total: 0;
        while[i > 0;
            total: total + (2 * xval * coeffs[i]) + coeffs[i - 1];
            i: i - 2;
        ];
        :total;
    };

    x_current: x_start;

    i: 0;
    while[(i < 1000) and (not (0 = df[x;degree;x_current]));
        x_current: x_current - (f[x;degree;x_current] % df[x;degree;x_current]);
        i: i + 1;
    ];

    : x_current;
    };
