        if[(gpa > 3.3) and not(gpa > 3.7);
            grade:"A-";
            ];

        if[(gpa > 3.0) and not(gpa > 3.3);
            grade:"B+";
            ];

        if[(gpa > 2.7) and not(gpa > 3.0);
            grade:"B";
            ];

        if[(gpa > 2.3) and not(gpa > 2.7);
            grade:"B-";
            ];

        if[(gpa > 2.0) and not(gpa > 2.3);
            grade:"C+";
            ];

        if[(gpa > 1.7) and not(gpa > 2.0);
            grade:"C";
            ];

        if[(gpa > 1.3) and not(gpa > 1.7);
            grade:"C-";
            ];

        if[(gpa > 1.0) and not(gpa > 1.3);
            grade:"D+";
            ];

        if[(gpa > 0.7) and not(gpa > 1.0);
            grade:"D";
            ];

        if[(gpa > 0.0) and not(gpa > 0.7);
            grade:"D-";
            ];

